// Map variable type codes to their corresponding component classes
export const VARIABLE_TYPE_TO_NAME: Record<string, string> = {
    '1': YesNoVariable.name,
    '2': MultiLineTextVariable.name,
    '3': MultipleChoiceVariable.name,
    '4': NumericScaleVariable.name,
    '5': SelectBoxVariable.name,
    '6': SingleLineTextVariable.name,
    '7': CheckboxVariable.name,
    '8': ReferenceVariable.name,
    '9': DateVariable.name,
    '10': DateTimeVariable.name,
    '11': LabelVariable.name,
    '12': BreakVariable.name,
    '14': CustomVariable.name,
    '15': UIPageVariable.name,
    '16': WideSingleLineTextVariable.name,
    '17': CustomWithLabelVariable.name,
    '18': LookupSelectBoxVariable.name,
    '19': ContainerStartVariable.name,
    '20': ContainerEndVariable.name,
    '21': ListCollectorVariable.name,
    '22': LookupMultipleChoiceVariable.name,
    '23': HtmlVariable.name,
    '24': ContainerSplitVariable.name,
    '25': MaskedVariable.name,
    '26': EmailVariable.name,
    '27': UrlVariable.name,
    '28': IpAddressVariable.name,
    '29': DurationVariable.name,
    '31': RequestedForVariable.name,
    '32': RichTextLabelVariable.name,
    '33': AttachmentVariable.name,
}

// Reverse mapping from API name to type code
export const VARIABLE_TYPE_TO_API: Record<string, string> = Object.fromEntries(
    Object.entries(VARIABLE_TYPE_TO_NAME).map(([key, value]) => [value, key])
)

export const VARIABLE_NAME_TO_TYPE = Object.fromEntries(
    Object.entries(VARIABLE_TYPE_TO_NAME).map(([key, value]) => [value, key])
) as Record<keyof typeof VARIABLE_TYPE_TO_NAME, string>

/**
 * Gets the variable type code from its class name
 * @param className - The class name of the variable (e.g., 'ReferenceVariable')
 * @returns The corresponding type code or '6' (SingleLineText) as default
 */
export function getVariableTypeFromName(className: string): string {
    return VARIABLE_NAME_TO_TYPE[className] || '6' // Default to SingleLineText if not found
}

// Define the default template constant
export const DEFAULT_SAVE_SCRIPT = `/** This script is executed before the Record is generated
* \`current\`- GlideRecord produced by Record Producer
* Don't use \`current.update()\` or \`current.insert()\` as the record is generated by Record Producer
* Don't use \`current.setValue('sys_class_name', 'xxx')\` as this will trigger reparent flow and can cause data loss
* Avoid \`current.setAbortAction()\` and generate a separate record
* Use \`producer.var1\` to access variables
*/`

